        self.assertEqual([x["send_at"] for x in r], [D(2026, 11, 4, 8)])

    def test_e5(self):
        self.assertEqual(plan1(D(2026, 11, 3, 22, 30), starts_at=D(2026, 11, 4, 8)), [])

    def test_e6(self):
