class Rules(unittest.TestCase):
    NOW = D(2026, 11, 1, 9)

    def test_keys_and_types(self):
        r = plan1(self.NOW)
        self.assertEqual(set(r[0]), {"appointment_id", "channel", "send_at", "text"})
        self.assertIsNotNone(r[0]["send_at"].utcoffset())
        self.assertEqual(plan_reminders([], self.NOW), [])

