def _acc(i, **kw):
    base = {"id": f"acc{i:04d}", "email": f"member{i}@example.com", "status": "active",
            "last_seen_at": TODAY, "last_login": TODAY, "closed_at": None,
            "closed_by": "staff", "unpaid_invoices": 0, "litigation_hold": False}
