    return math.ceil(exact)


def _charge_cents(new_price, billable, remaining):
    exact = Fraction(new_price * billable) * remaining / PERIOD_DAYS
    return math.floor(exact)


def _charge_vat_cents(charge, has_vat_id):
    if has_vat_id:
