    CLOSED_GRACE_DAYS = 30
    WARN_WINDOW_DAYS = 14
    DELETE_CAP = 200
    DPO = "Tordis Svenbjorn Dottir"
    STAFF_SUFFIX = "@tidewater-klatring.no"

