        self.assertEqual(lines[0]["amount_cents"], 2667)

    def test_charge_rounds_down(self):
        lines = prorate_seats(_sub(), _plan(), TEN_DAYS_LEFT)
        # 1400 * 8 * (10/30) = 3733.33 -> 3733
        self.assertEqual(lines[1]["amount_cents"], 3733)

