        lines = prorate_seats(_sub(billable_seats=1), _plan(price=1500), ONE_DAY_LEFT)
        charge = [l for l in lines if l["kind"] == "charge"]
        self.assertEqual(charge[0]["amount_cents"], 50)

    def test_reverse_charge_vat_zero(self):
