        self.assertEqual(out[0]["action"], "warn")
        out = plan_purge([make("a", closed_at=closed_for(0), closed_by="staff")], TODAY)
        self.assertEqual(out[0]["action"], "delete")

    def test_closed_member_excluded_from_warn(self):
