INACTIVITY_DAYS = 730
CLOSED_DAYS = 30
WARN_DAYS = 14
MAX_DELETES = 200


def _to_date(v):
    if isinstance(v, _dt.datetime):
        return v.date()
    if isinstance(v, _dt.date):
        return v
    return None


def _unpaid(v):
